/**
 * routeId、ルート名 (worldName)、または現在地の座標から走行中のコースプロファイルを特定する。
 */
export function findActiveRouteProfile(opts: {
  routeId?: number
  routeName?: string
  courseId?: number
  mapX?: number
  mapY?: number
}): ZwiftRouteProfile | null {
  if (opts.routeId && opts.routeId > 0) {
    const byId = ZWIFT_ROUTE_PROFILES.find((r) => r.id === opts.routeId)
    if (byId) return byId
  }
  if (opts.routeName) {
    const norm = opts.routeName.trim().toLowerCase()
    if (norm.length > 0) {
      const exact = ZWIFT_ROUTE_PROFILES.find(
        (r) => r.name.toLowerCase() === norm && (!opts.courseId || r.courseId === opts.courseId)
      ) ?? ZWIFT_ROUTE_PROFILES.find((r) => r.name.toLowerCase() === norm)
      if (exact) return exact
      const partial = ZWIFT_ROUTE_PROFILES.find(
        (r) =>
          (r.name.toLowerCase().includes(norm) || norm.includes(r.name.toLowerCase())) &&
          (!opts.courseId || r.courseId === opts.courseId)
      )
      if (partial) return partial
    }
  }
  if (opts.courseId !== undefined && opts.mapX !== undefined && opts.mapY !== undefined) {
    const candidates = ZWIFT_ROUTE_PROFILES.filter((r) => r.courseId === opts.courseId)
    let best: ZwiftRouteProfile | null = null
    let bestDist = Infinity
    for (const r of candidates) {
      for (let i = 0; i < r.points.length; i += 2) {
        const d = Math.hypot(r.points[i][0] - opts.mapX, r.points[i][1] - opts.mapY)
        if (d < bestDist) {
          bestDist = d
          best = r
        }
      }
    }
    if (best) return best
  }
  return null
}

/**
 * コース全体の座標列 (96点) に対する現在の自車位置 (mapX, mapY) と進行方向ベクトルから、
 * コース断面プロファイル上の現在地割合 (0.0 〜 1.0) と標高を算出する。
 *
 * 同じ道路を複数回通る周回コース（例: Sacré Trois! 等）で別周回へワープしないよう、
 * 前回の進行度 (prevProgress) による時間的連続性と走行距離 (fallbackDistanceM) による
 * 周回ガイドをスコアに組み込む。
 */
export function computeCourseProgress(
  route: ZwiftRouteProfile,
  mapX: number,
  mapY: number,
  dirX?: number,
  dirY?: number,
  fallbackDistanceM?: number,
  prevProgress?: number
): { progress: number; elevationM: number } {
  const pts = route.points
  if (pts.length < 2) return { progress: 0, elevationM: route.elevations[0] ?? 0 }
  const hasDir = dirX !== undefined && dirY !== undefined && Math.hypot(dirX, dirY) > 0.01
  const hasPrev = prevProgress !== undefined && Number.isFinite(prevProgress)
  const hasDist =
    fallbackDistanceM !== undefined &&
    Number.isFinite(fallbackDistanceM) &&
    fallbackDistanceM >= 0 &&
    route.distanceM > 100
  const distProgress = hasDist
    ? (((fallbackDistanceM! % route.distanceM) + route.distanceM) % route.distanceM) / route.distanceM
    : undefined

  let bestScore = Infinity
  let bestRawDist = Infinity
  let bestProgress = hasPrev ? prevProgress! : (distProgress ?? 0)
  const nSegs = pts.length - 1

  for (let i = 0; i < nSegs; i++) {
    const p0 = pts[i]
    const p1 = pts[i + 1]
    const sx = p1[0] - p0[0]
    const sy = p1[1] - p0[1]
    const segLenSq = sx * sx + sy * sy
    let t = 0
    if (segLenSq > 1) {
      t = Math.max(0, Math.min(1, ((mapX - p0[0]) * sx + (mapY - p0[1]) * sy) / segLenSq))
    }
    const projX = p0[0] + sx * t
    const projY = p0[1] + sy * t
    const dist = Math.hypot(mapX - projX, mapY - projY)
    const candP = (i + t) / nSegs

    // 1. 進行方向ペナルティ（逆走セグメントを除外）
    let dirPenalty = 0
    if (hasDir && segLenSq > 1) {
      const segLen = Math.sqrt(segLenSq)
      const dot = (sx / segLen) * dirX! + (sy / segLen) * dirY!
      if (dot < -0.15) dirPenalty = 25000
    }

    // 2. 前回進行度からの時間的連続性ペナルティ（別周回へのワープを防止）
    //    ゴール通過後の次周突入 (prev > 0.94 → cand < 0.06) のみ順方向ラップを許可し、
    //    スタート直後からゴール直前 (prev < 0.06 → cand > 0.94) への逆方向ラップは禁止する。
    let continuityPenalty = 0
    if (hasPrev) {
      const linearDelta = candP - prevProgress!
      let fwd: number | null = null
      let bwd: number | null = null
      if (linearDelta >= 0) {
        fwd = linearDelta
      } else if (prevProgress! > 0.94 && candP < 0.06) {
        fwd = candP + 1 - prevProgress!
      } else {
        bwd = -linearDelta
      }

      if (fwd !== null && fwd <= 0.06) {
        // 通常の1ステップ前進
        continuityPenalty = fwd * 12000
      } else if (bwd !== null && bwd <= 0.015) {
        // 微小なGPS揺らぎによる後退
        continuityPenalty = bwd * 35000
      } else {
        // 別周回など大きく離れた位置へのジャンプを強く抑制
        const jump = fwd !== null ? fwd : bwd!
        continuityPenalty = 50000 + jump * 150000
      }
    }

    // 3. 累積走行距離からの周回ガイドペナルティ（初回ロックオン時の周回誤認を防止）
    //    スタート直後 (distProgress < 0.1) にゴール直前 (candP > 0.9) を誤認しないよう線形差を基準とする。
    let distPenalty = 0
    if (distProgress !== undefined) {
      let diff = Math.abs(candP - distProgress)
      if (distProgress > 0.95 && candP < 0.05) {
        diff = Math.min(diff, candP + 1 - distProgress)
      }
      distPenalty = diff * (hasPrev ? 5000 : 55000)
    }

    const score = dist + dirPenalty + continuityPenalty + distPenalty
    if (score < bestScore) {
      bestScore = score
      bestRawDist = dist
      bestProgress = candP
    }
  }

  // もしコースから大きく外れている場合は走行距離からの周回割合をフォールバックとして使用
  if (bestRawDist > 40000 && distProgress !== undefined) {
    bestProgress = distProgress
  }

  const clamped = Math.max(0, Math.min(1, bestProgress))
  const exactIdx = clamped * (route.elevations.length - 1)
  const i0 = Math.min(route.elevations.length - 1, Math.floor(exactIdx))
  const i1 = Math.min(route.elevations.length - 1, i0 + 1)
  const frac = exactIdx - i0
  const elevationM = route.elevations[i0] * (1 - frac) + route.elevations[i1] * frac
  return { progress: clamped, elevationM }
}
